57	/**
58	 * Capture's What's in view (R-3qz): the frame as it is on screen, with what's
59	 * typed or drawn in it, which no page opened afresh can hold. The menu closes
60	 * first, so it isn't in the picture; the shell pictures the frame's box, at
61	 * the page's own pixels when a size scales it down (1 / --scale); the PNG goes
62	 * in the form's `picture`, which the server keeps as it is. If the shell
63	 * can't, the form goes without it, and the server opens the page afresh.
64	 */
65	async function captureShown(button) {
66	  const form = button.form;
67	  const input = form.querySelector('[data-capture-picture]');
68	  const frame = button.closest('.design')?.querySelector('.design-frame iframe');
69	  const menu = button.closest('details');
70	  if (menu) menu.open = false;
71	  if (input) input.value = '';
72	  if (input && frame) {
73	    try {
74	      // Two frames: the menu's closing is painted before the picture.
75	      await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
76	      const box = frame.getBoundingClientRect();
77	      const scale = Number(getComputedStyle(frame.closest('.device') ?? frame).getPropertyValue('--scale')) || 1;
78	      const answer = JSON.parse(await desktop.capture({ x: box.left + scrollX, y: box.top + scrollY, width: box.width, height: box.height }, 1 / scale));
79	      const bytes = Uint8Array.from(atob(answer.data), c => c.charCodeAt(0));
80	      const files = new DataTransfer();
81	      files.items.add(new File([bytes], form.elements.namedItem('name')?.value || 'Capture.png', { type: 'image/png' }));
82	      input.files = files.files;
83	    } catch (error) {
84	      console.error('Prelude desktop: the window couldn’t picture the frame, so the page is opened afresh.', error);

